function ensureNotice(){if(notice)return;const style=document.createElement('style');style.textContent='.tf-update{position:fixed;z-index:10000;right:max(12px,env(safe-area-inset-right));top:max(12px,env(safe-area-inset-top));width:min(360px,calc(100vw - 24px));box-sizing:border-box;padding:14px;border:1px solid #d7bda4;border-radius:14px;background:#fffaf4;color:#49352b;box-shadow:0 6px 28px #49352b26;font:14px/1.5 system-ui,sans-serif}.tf-update[hidden]{display:none}.tf-update p{margin:0 0 8px;font-size:12px;line-height:1.5}.tf-update strong{display:block;margin-bottom:6px}.tf-update ul{margin:0 0 12px;padding-left:1.4em;font-size:13px;line-height:1.55}.tf-update li+li{margin-top:4px}.tf-update-actions{display:flex;gap:8px;flex-wrap:wrap}.tf-update button{min-height:44px;padding:8px 16px;font:inherit;border:1px solid #b88b63;border-radius:10px;background:#fff;color:#75421c}.tf-update button:first-child{background:#9c4a12;color:white}.tf-update button:focus-visible,.tf-update-reminder:focus-visible{outline:3px solid #c57930;outline-offset:2px}.tf-update-reminder{position:fixed;z-index:10000;right:max(12px,env(safe-area-inset-right));top:max(12px,env(safe-area-inset-top));min-height:44px;padding:8px 12px;border:1px solid #b88b63;border-radius:10px;background:#fffaf4;color:#75421c;font:14px system-ui,sans-serif}.tf-update-reminder[hidden]{display:none}';document.head.append(style);notice=document.createElement('section');notice.className='tf-update';notice.hidden=true;notice.setAttribute('aria-label','Time Flight の更新');notice.setAttribute('role','region');const title=document.createElement('strong');title.textContent='新しい版があります';status=document.createElement('p');status.setAttribute('role','status');status.setAttribute('aria-live','polite');const changes=document.createElement('ul');changes.className='tf-update-changes';changes.setAttribute('aria-label','今回の更新内容');for(const text of releaseChanges){const item=document.createElement('li');item.textContent=text;changes.append(item);}const actions=document.createElement('div');actions.className='tf-update-actions';update=document.createElement('button');update.type='button';update.textContent='更新する';later=document.createElement('button');later.type='button';later.textContent='キャンセル';update.onclick=accept;later.onclick=()=>{dismissedRelease=candidate?.release||'';notice.hidden=true;reminder.hidden=false;reminder.focus?.();};actions.append(update,later);notice.append(title,status,changes,actions);reminder=document.createElement('button');reminder.className='tf-update-reminder';reminder.type='button';reminder.textContent='更新あり';reminder.hidden=true;reminder.setAttribute('aria-label','新しい版の更新案内を開く');reminder.onclick=()=>{dismissedRelease='';show(candidate,candidate.worker);update.focus?.();};document.body.append(notice,reminder);}
